// Allow only the formatting generated by our small rich-text editor.
// All input is escaped first; approved tags and safe styles are restored.
const decodeEntities=(value:string)=>value.replace(/&(?:amp|lt|gt|quot|#39);/g,entity=>({'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'\"','&#39;':"'"} as Record<string,string>)[entity]||entity);
const escapeHtml=(value:string)=>value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const colors=new Set(['#252722','#a17a36','#b42318','#146b46','#2257a5','#ffffff','#fff3b0']);
const sizes=new Set(['14px','16px','18px','22px','28px']);
function normalizedColor(value:string){const rgb=value.match(/^rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)$/);return rgb?'#'+rgb.slice(1).map(n=>Number(n).toString(16).padStart(2,'0')).join(''):value}
function safeStyle(input:string){
 const rules:string[]=[];
 for(const declaration of input.split(';')){
  const [key,...rest]=declaration.split(':');const name=key?.trim().toLowerCase(),value=normalizedColor(rest.join(':').trim().toLowerCase());
  if(name==='color'&&colors.has(value))rules.push('color:'+value);
  if(name==='background-color'&&colors.has(value))rules.push('background-color:'+value);
  if(name==='font-size'&&sizes.has(value))rules.push('font-size:'+value);
  if(name==='text-align'&&['left','center','right'].includes(value))rules.push('text-align:'+value);
 }
 return rules.join(';');
}
export function sanitizeCaseDetails(input:string){
 // Old plain-text descriptions stay plain text. New editor markup starts with a marker.
 if(!input.startsWith('<!-- rich-case -->'))return escapeHtml(input).replace(/\r?\n/g,'<br>');
 const html=input.slice('<!-- rich-case -->'.length);
 const tagPattern=/<\/?(?:p|div|br|strong|b|em|i|u|ul|ol|li|span|font|h2|h3)(?:\s[^<>]*?)?\s*\/?\s*>/gi;
 let output='',index=0;let match:RegExpExecArray|null;
 while((match=tagPattern.exec(html))){
  output+=escapeHtml(decodeEntities(html.slice(index,match.index)));
  const tag=match[0],closing=/^<\//.test(tag),name=(tag.match(/^<\/?([a-z0-9]+)/i)||[])[1]?.toLowerCase();
  if(!name){index=tagPattern.lastIndex;continue}
  const normalized=name==='font'?'span':name==='div'?'p':name==='b'?'strong':name==='i'?'em':name;
  if(closing){if(normalized!=='br')output+='</'+normalized+'>'}
  else if(normalized==='br')output+='<br>';
  else{
   const styleMatch=tag.match(/\bstyle\s*=\s*(?:"([^"]*)"|'([^']*)')/i);
   let style=safeStyle(styleMatch?.[1]||styleMatch?.[2]||'');
   if(name==='font'){
    const color=tag.match(/\bcolor\s*=\s*["']?(#[0-9a-f]{6})/i)?.[1]?.toLowerCase();
    const size=tag.match(/\bsize\s*=\s*["']?([1-7])/i)?.[1];
    if(color&&colors.has(color))style+=(style?';':'')+'color:'+color;
    if(size){const mapped=({1:'14px',2:'14px',3:'16px',4:'18px',5:'22px',6:'28px',7:'28px'} as Record<string,string>)[size];style+=(style?';':'')+'font-size:'+mapped}
   }
   output+='<'+normalized+(style?' style="'+style+'"':'')+'>';
  }
  index=tagPattern.lastIndex;
 }
 output+=escapeHtml(decodeEntities(html.slice(index)));
 return output;
}
